/* @autogenerated */
import { computeAvatarSpec } from './avatar-text.service';

describe('computeAvatarSpec', () => {
  it('generates initials and aria label', () => {
    const spec = computeAvatarSpec('Luis de la Vega');

    expect(spec.initials).toBe('LV');
    expect(spec.ariaLabel).toBe('Icono de Luis de la Vega');
    expect(spec.bg).toContain('hsl(');
    expect(spec.fg).toMatch(/^#(000|fff)$/);
  });

  it('handles empty text', () => {
    const spec = computeAvatarSpec('');

    expect(spec.initials).toBe('•');
    expect(spec.ariaLabel).toBe('Icono');
  });

  it('uses email local part for initials', () => {
    const spec = computeAvatarSpec('john.doe@example.com');

    expect(spec.initials).toBe('JD');
  });

  it('is deterministic for the same input', () => {
    const first = computeAvatarSpec('Same Name');
    const second = computeAvatarSpec('Same Name');

    expect(second.bg).toBe(first.bg);
    expect(second.fg).toBe(first.fg);
  });
});
